import{_ as l,a0 as p,w as o,s as d,ao as c,I as n,x as s,a1 as e,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"如何在 Rocky Linux 9 / AlmaLinux 9 上安装 KVM | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Rocky Linux 9 / AlmaLinux 9 上安装 KVM | LCTT (202305) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Rocky Linux 9 / AlmaLinux 9 上安装 KVM | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Rocky Linux 9 / AlmaLinux 9 上安装 KVM | LCTT (202305) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202305/20230403.4 ⭐️⭐️ How to Install KVM on Rocky Linux 9  AlmaLinux 9","title":"如何在 Rocky Linux 9 / AlmaLinux 9 上安装 KVM","tag":"202305","desc":""},"relativePath":"202305/20230403.4 ⭐️⭐️ How to Install KVM on Rocky Linux 9  AlmaLinux 9.md","filePath":"[post].md"}'),h={name:"202305/20230403.4 ⭐️⭐️ How to Install KVM on Rocky Linux 9  AlmaLinux 9.md"};function r(g,i,u,k,b,m){const a=p("Link");return o(),d("div",null,[i[15]||(i[15]=c(`<h1 id="如何在-rocky-linux-9-almalinux-9-上安装-kvm" tabindex="-1">如何在 Rocky Linux 9 / AlmaLinux 9 上安装 KVM <a class="header-anchor" href="#如何在-rocky-linux-9-almalinux-9-上安装-kvm" aria-label="Permalink to “如何在 Rocky Linux 9 / AlmaLinux 9 上安装 KVM”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202305/25/155857v1e939ckoj3eaxe3.jpg" alt=""></p><blockquote><p>在本指南中，我们演示了如何在 Rocky Linux 9 / Alma Linux 9 上安装 KVM。</p></blockquote><p>KVM 是 <ruby>内核虚拟机<rt>Kernel Virtualization Machine</rt></ruby> 的简称，是一个为 Linux 内核设计的开源虚拟化平台。它是一种 1 类管理程序，或通常称为裸机管理程序。它允许用户创建和管理多台客户机，这些可以在 Linux 或 Windows 操作系统中创建。</p><p>与大多数虚拟化平台一样，它将硬件资源（如 CPU、内存、存储、网络、图形等）抽象化，并将它们分配给独立于宿主机运行的客户机。</p><h3 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to “先决条件”">​</a></h3><ul><li>预装 Rocky Linux 9 / AlmaLinux 9</li><li>具有管理员权限的 sudo 用户</li><li>互联网连接</li></ul><h3 id="_1、验证是否启用了硬件虚拟化" tabindex="-1">1、验证是否启用了硬件虚拟化 <a class="header-anchor" href="#_1、验证是否启用了硬件虚拟化" aria-label="Permalink to “1、验证是否启用了硬件虚拟化”">​</a></h3><p>首先，你需要验证你的系统是否启用了虚拟化功能。在大多数现代系统上，此功能已在 BIOS 中启用。但可以肯定的是，你可以验证是否如图所示启用了虚拟化。</p><p>该命令探测是否存在 VMX（<ruby>虚拟机扩展<rt>Virtual Machine Extension</rt></ruby>），它是英特尔硬件虚拟化的 CPU 标志，或 SVM，它是 AMD 硬件虚拟化的标志。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat /proc/cpuinfo | egrep &quot;vmx|svm&quot;</span></span></code></pre></div><p>从以下输出中，你可以看到我们的系统启用了英特尔硬件虚拟化：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/Intel-VT-Check-CPU-Flags-Grep-Command.png" alt=""></p><h3 id="_2、在-rocky-linux-9-almalinux-9-上安装-kvm" tabindex="-1">2、在 Rocky Linux 9 / AlmaLinux 9 上安装 KVM <a class="header-anchor" href="#_2、在-rocky-linux-9-almalinux-9-上安装-kvm" aria-label="Permalink to “2、在 Rocky Linux 9 / AlmaLinux 9 上安装 KVM”">​</a></h3><p>确保启用虚拟化后，下一步就是安装 KVM 和管理工具。为此，请运行以下 <code>dnf</code> 命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install qemu-kvm virt-manager libvirt virt-install virt-viewer virt-top bridge-utils  bridge-utils virt-top libguestfs-tools -y</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/dnf-install-lvm-qemu-rocky-almalinux9.png" alt=""></p><p>安装完成后，运行以下命令检查是否已加载所需的 KVM 模块。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lsmod | grep kvm</span></span></code></pre></div><p>你应该得到以下输出以确认已加载必要的模块：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/List-KVM-Module-lsmod-command.png" alt=""></p><h3 id="_3、启动并启用-libvirtd-守护进程" tabindex="-1">3、启动并启用 libvirtd 守护进程 <a class="header-anchor" href="#_3、启动并启用-libvirtd-守护进程" aria-label="Permalink to “3、启动并启用 libvirtd 守护进程”">​</a></h3><p>在下一步中，一定要启动 libvirtd 守护进程。这是一个服务器端守护程序组件，可在虚拟化的客户机上运行和管理任务。它用于管理虚拟化技术，例如 Xen、KVM 和 ESXi 等等。</p><p>要启动 libvirtd 守护进程，请运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl start libvirtd</span></span></code></pre></div><p>请务必启用该服务以在引导时启动：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl enable --now libvirtd</span></span></code></pre></div><p>验证 libvirtd 守护进程是否正在运行，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl status libvirtd</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/Libvirtd-Service-Status-RockyLinux-AlmaLinux.png" alt=""></p><h3 id="_4、设置桥接接口" tabindex="-1">4、设置桥接接口 <a class="header-anchor" href="#_4、设置桥接接口" aria-label="Permalink to “4、设置桥接接口”">​</a></h3><p>到目前为止，我们已经安装了 KVM 和所有管理工具，事实上，我们可以继续启动虚拟机。但是，如果我们可以从管理程序网络外部访问虚拟机，那就太好了。为此，我们需要创建一个桥接接口。</p><p>首先，确定系统上的网络接口。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nmcli connection show</span></span></code></pre></div><p>从输出来看，<code>ens160</code> 是活动的网络接口，请务必注意你的情况下的接口，因为你将一路使用它。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/nmcli-connection-show-output-rockylinux9.png" alt=""></p><p>要开始创建网桥，首先，使用以下语法用其 UUID 删除连接：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nmcli connection delete UUID</span></span></code></pre></div><p>在我们的例子中，命令将是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nmcli connection delete 19e98123-9a84-30a6-bc59-a7134446bb26</span></span></code></pre></div><p>你将收到连接已成功删除的确认信息。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/nmcli-connection-delete-output.png" alt=""></p><p>在继续进行之前，最好准备好以下详细信息：</p><ul><li>网桥名称 – 新网桥的首选名称（例如 <code>br1</code>）</li><li>设备名称 – 这是你的网络接口的名称。它将作为网桥的从属设备（例如，<code>ens160</code>）</li><li>IP 地址/子网 – 桥接网络的 IP 地址和子网（例如 <code>192.168.2.50/24</code>）。请注意，这应该与你的网络子网和 IP 地址相对应。</li><li>网关 – 你网络的默认网关地址（例如 <code>192.168.2.1</code>）</li><li>DNS1 和 DNS2 – 首选 DNS 地址（例如 <code>8.8.8.8</code> 和 <code>8.8.4.4</code>）</li></ul><p>继续，使用以下语法创建一个新的桥接接口。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nmcli connection add type bridge autoconnect yes con-name BRIDGE NAME ifname BRIDGE NAME</span></span></code></pre></div><p>在我们的例子中，<code>br1</code> 是首选的网桥接口名称。因此，命令将如图所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nmcli connection add type bridge autoconnect yes con-name br1 ifname br1</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/create-Bridge-nmcli-rockylinux-almalinux.png" alt=""></p><p>在接下来的步骤中，你将通过指定 IP 子网、网关和 DNS 值来修改网桥。</p><p>首先使用以下语法指定 IP 子网：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nmcli connection modify BRIDGE NAME ipv4.addresses IP ADDRESS/SUBNET ipv4.method manual</span></span></code></pre></div><p>根据我们的设置，命令将是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nmcli connection modify br1 ipv4.addresses 192.168.2.150/24 ipv4.method manual</span></span></code></pre></div><p>接下来，使用以下语法指定网关地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nmcli connection modify BRIDGE NAME ipv4.gateway GATEWAY</span></span></code></pre></div><p>根据我们的网络，该命令采用以下格式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nmcli connection modify br1 ipv4.gateway 192.168.2.1</span></span></code></pre></div><p>DNS 地址的语法如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nmcli connection modify BRIDGE NAME ipv4.dns DNS1 +ipv4.dns DNS2</span></span></code></pre></div><p>该命令采用以下格式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nmcli connection modify br1 ipv4.dns 8.8.8.8 +ipv4.dns 8.8.4.4</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/Add-IP-Gateway-DNS-Network-Bridge-RockyLinux-AlmaLinux.png" alt=""></p><p>此后，使用以下命令添加网桥从属设备：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nmcli connection add type bridge-slave autoconnect yes con-name DEVICE NAME ifname DEVICE NAME master BRIDGE NAME</span></span></code></pre></div><p>使用我们的值，命令如图所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nmcli connection add type bridge-slave autoconnect yes con-name ens160 ifname ens160 master br1</span></span></code></pre></div><p>你将收到以下确认信息，表明已成功添加网桥从属设备。请记住，桥接从属设备是你的网络接口或适配器。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/Network-Bridge-AutoConnect-Nmcli-RockyLinux-AlmaLinux.png" alt=""></p><p>要确认网桥已创建，请运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nmcli connection show</span></span></code></pre></div><p>从输出中，你可以看到列出了网桥接口。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/nmcli-connection-show-after-bridge-creation.png" alt=""></p><p>激要活它，请运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nmcli connection up br1</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/Network-Bridge-Up-Command-RockyLinux-AlmaLinux.png" alt=""></p><p>此外，你可以使用 <code>ip addr</code> 命令验证：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ip addr | grep br1</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/Check-Bridge-Ip-address-RockyLinux-AlmaLinux.png" alt=""></p><p>最后，编辑网桥配置文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vi /etc/qemu-kvm/bridge.conf</span></span></code></pre></div><p>添加以下行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>allow all</span></span></code></pre></div><p>然后重新启动虚拟化守护进程以应用更改</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl restart libvirtd</span></span></code></pre></div><h3 id="_5、创建虚拟机" tabindex="-1">5、创建虚拟机 <a class="header-anchor" href="#_5、创建虚拟机" aria-label="Permalink to “5、创建虚拟机”">​</a></h3><p>安装 KVM 并配置桥接连接后，现在让我们创建一个虚拟机。在执行之前，为登录用户分配必要的所有权，以便在不切换到 root 的情况下运行命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chown -R $USER:libvirt /var/lib/libvirt/</span></span></code></pre></div><p>在命令行上，我们将使用以下语法使用 Ubuntu 20.04 ISO 镜像创建虚拟机。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ virt-install \\</span></span>
<span class="line"><span>    --name Ubuntu \\</span></span>
<span class="line"><span>    --ram 2048 \\</span></span>
<span class="line"><span>    --vcpus 2 \\</span></span>
<span class="line"><span>    --disk path=/var/lib/libvirt/images/ubuntu-20.04.img,size=15 \\</span></span>
<span class="line"><span>    --os-variant ubuntu20.04 \\</span></span>
<span class="line"><span>    --network bridge=br1,model=virtio \\</span></span>
<span class="line"><span>    --graphics vnc,listen=0.0.0.0 \\</span></span>
<span class="line"><span>    --console pty,target_type=serial \\</span></span>
<span class="line"><span>    --cdrom /home/linuxtechi/Downloads/ubuntu-20.04.4-desktop-amd64.iso</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/Virt-Install-command-RockyLinux-AlmaLinux.png" alt=""></p><p>执行该命令后，将启动图形屏幕会话，并开始安装客户操作系统。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/VNC-connection-KVM-VM-RockyLinux-AlmaLinux.png" alt=""></p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/VNC-Console-KVM-GUI-RockyLinux-AlmaLinux.png" alt=""></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>我们关于如何在 Rocky Linux 9 / AlmaLinux 9 上安装 KVM 的文章到此结束，非常欢迎你提供反馈。</p><p><em>（题图：MJ/a364d6e3-0c59-4be8-bf02-5df078359429）</em></p><hr>`,98)),n("p",null,[i[1]||(i[1]=s("via: ",-1)),e(a,{href:"https://www.linuxtechi.com/install-kvm-on-rocky-linux-almalinux/"},{default:t(()=>[...i[0]||(i[0]=[s("https://www.linuxtechi.com/install-kvm-on-rocky-linux-almalinux/",-1)])]),_:1})]),n("p",null,[i[6]||(i[6]=s("作者：",-1)),e(a,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:t(()=>[...i[2]||(i[2]=[s("Pradeep Kumar",-1)])]),_:1}),i[7]||(i[7]=s(" 选题：",-1)),e(a,{href:"https://github.com/lkxed/"},{default:t(()=>[...i[3]||(i[3]=[s("lkxed",-1)])]),_:1}),i[8]||(i[8]=s(" 译者：",-1)),e(a,{href:"https://github.com/geekpi"},{default:t(()=>[...i[4]||(i[4]=[s("geekpi",-1)])]),_:1}),i[9]||(i[9]=s(" 校对：",-1)),e(a,{href:"https://github.com/wxy"},{default:t(()=>[...i[5]||(i[5]=[s("wxy",-1)])]),_:1})]),n("p",null,[i[12]||(i[12]=s("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...i[10]||(i[10]=[s("LCTT",-1)])]),_:1}),i[13]||(i[13]=s(" 原创编译，",-1)),e(a,{href:"https://linux.cn/"},{default:t(()=>[...i[11]||(i[11]=[s("Linux中国",-1)])]),_:1}),i[14]||(i[14]=s(" 荣誉推出",-1))])])}const v=l(h,[["render",r]]);export{f as __pageData,v as default};
